#!/usr/bin/env bash
# Rebuilds tests/fixtures/rs_accessors.h from rs_accessors.c (needs clang, ld.lld, llvm-nm,
# llvm-readelf, python3). The header carries the flat image, the symbol offsets and the
# dynamic relocations, so the selftest can lay the library out the way the dynamic linker would.
set -euo pipefail
cd "$(dirname "$0")"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
clang --target=aarch64-linux-android29 -O2 -fPIC -fno-stack-protector -mbranch-protection=standard \
      -c rs_accessors.c -o "$tmp/rs.o"
ld.lld -shared -z max-page-size=4096 --unresolved-symbols=ignore-all -z notext "$tmp/rs.o" -o "$tmp/rs.so"
llvm-nm --defined-only "$tmp/rs.so" > "$tmp/syms.txt"
llvm-readelf -r --wide "$tmp/rs.so" > "$tmp/relocs.txt"
python3 - "$tmp" > rs_accessors.h <<'PY'
import re, sys
tmp = sys.argv[1]
import struct
elf = open(f"{tmp}/rs.so", "rb").read()
phoff, = struct.unpack_from("<Q", elf, 0x20)
phentsize, phnum = struct.unpack_from("<HH", elf, 0x36)
loads = []
for i in range(phnum):
    p_type, p_flags, p_offset, p_vaddr, p_paddr, p_filesz, p_memsz, p_align = struct.unpack_from("<IIQQQQQQ", elf, phoff + i * phentsize)
    if p_type == 1:  # PT_LOAD: lay the file out at its virtual addresses, like the loader
        loads.append((p_offset, p_vaddr, p_filesz, p_memsz))
size = max(v + m for _, v, _, m in loads)
size = (size + 0xFFF) & ~0xFFF
buf = bytearray(size)
for off, vaddr, filesz, memsz in loads:
    buf[vaddr:vaddr + filesz] = elf[off:off + filesz]
image = bytes(buf)
syms = {}
for line in open(f"{tmp}/syms.txt"):
    parts = line.split()
    if len(parts) == 3 and parts[1] in "TtBbDd":
        syms[parts[2]] = int(parts[0], 16)
relocs = []
for line in open(f"{tmp}/relocs.txt"):
    m = re.match(r"\s*([0-9a-f]{16})\s+[0-9a-f]+\s+(R_AARCH64_\w+)\s*(?:([0-9a-f]{16})\s+(\S+)\s*\+\s*([0-9a-f]+))?(?:\s*([0-9a-f]+))?", line)
    if not m:
        continue
    offset, kind, symvalue, name, addend, plain = m.groups()
    defined = 1 if (name and name in syms) else 0
    value = syms.get(name, 0) if name else 0
    add = int(addend or plain or "0", 16)
    relocs.append((int(offset, 16), kind, value, add, defined))
print("// Generated by build_rs_accessors.sh from rs_accessors.c. Do not edit.")
print("#pragma once")
print("#include <cstdint>")
print("namespace rs_fixture {")
for name, value in sorted(syms.items()):
    if re.match(r"^[A-Za-z_]\w*$", name):
        print(f"    inline constexpr uint64_t {name} = 0x{value:x};")
print("    enum RelocKind { Relative, Symbol, Other };")
print("    struct Reloc { uint64_t offset; RelocKind kind; uint64_t value; uint64_t addend; bool defined; };")
print("    inline const Reloc relocs[] = {")
for off, kind, value, add, defined in relocs:
    k = "Relative" if kind == "R_AARCH64_RELATIVE" else ("Symbol" if kind in ("R_AARCH64_GLOB_DAT", "R_AARCH64_JUMP_SLOT", "R_AARCH64_ABS64") else "Other")
    print(f"        {{0x{off:x}, {k}, 0x{value:x}, 0x{add:x}, {'true' if defined else 'false'}}},  // {kind}")
print("    };")
print(f"    inline constexpr uint64_t image_size = {len(image)};")
print("    inline const unsigned char image[] = {")
for i in range(0, len(image), 16):
    print("        " + ", ".join(f"0x{b:02x}" for b in image[i:i+16]) + ",")
print("    };")
print("}")
PY
llvm-objdump -d --no-show-raw-insn "$tmp/rs.so" > rs_accessors.disasm.txt
